import { useEffect, useRef, type ReactNode } from 'react';
import { Toolbar } from '@kerfjs/ui/toolbar';
import { PageHeader } from '@kerfjs/ui/page-header';
import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import { ResizableRegion, wireResizableRegions } from '@kerfjs/ui/resizable-region';
import '@kerfjs/ui/layout.css';
import './shell.css';

type Props = {
  inspectorWidth: number;
  onInspectorWidthChange: (width: number) => void;
  selectedSection: string;
  navigate: (section: string) => void;
  workspace: ReactNode;
  inspector: ReactNode;
};
// State, routes, and persisted width are supplied by the application.
export function AppShell(p: Props) {
  const root = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!root.current) return;
    const dispose = wireResizableRegions(root.current);
    return () => dispose();
  }, []);
  return <div ref={root} className="kui-layout app-shell">
    <a href="#workspace" className="skip-link">Skip to workspace</a>
    <Toolbar aria-label="Application toolbar"><strong>Workspace</strong></Toolbar>
    <div className="app-panes">
      <nav aria-label="Workspace navigation" className="kui-sidebar app-navigation">
        <section className="kui-sidebar-section" aria-label="Workspace">
          <MenuHeader>Workspace</MenuHeader>
          <MenuItem selected={p.selectedSection === 'projects'} onClick={() => p.navigate('projects')}>Projects</MenuItem>
          <MenuItem selected={p.selectedSection === 'activity'} onClick={() => p.navigate('activity')}>Activity</MenuItem>
        </section>
        <section className="kui-sidebar-section" aria-label="Account">
          <MenuHeader>Account</MenuHeader>
          <MenuItem selected={p.selectedSection === 'settings'} onClick={() => p.navigate('settings')}>Settings</MenuItem>
        </section>
      </nav>
      <main id="workspace" tabIndex={-1} className="app-workspace">
        <PageHeader title="Projects" />
        <div className="kui-pane app-scroll">{p.workspace}</div>
      </main>
      <ResizableRegion className="app-inspector-region" size={p.inspectorWidth}
        minSize={240} maxSize={480} onSizeChange={p.onInspectorWidthChange}
        aria-label="Resize inspector" aria-controls="inspector">
        <aside id="inspector" aria-label="Inspector" className="app-inspector">
          <PageHeader title="Inspector" />
          <div className="kui-pane app-scroll">{p.inspector}</div>
        </aside>
      </ResizableRegion>
    </div>
  </div>;
}

