.app-shell { block-size:100dvh; display:flex; flex-direction:column; overflow:hidden; }
.app-panes { flex:1; min-block-size:0; display:flex; }
.app-navigation { flex:0 0 15rem; overflow:auto; min-block-size:0; }
.app-workspace { flex:1; min-inline-size:0; min-block-size:0; display:flex; flex-direction:column; }
.app-inspector-region { flex:none; min-block-size:0; }
.app-inspector { block-size:100%; min-block-size:0; display:flex; flex-direction:column; }
.app-scroll { min-block-size:0; min-inline-size:0; flex:1; overflow:auto; overflow-wrap:anywhere; }
.skip-link { position:absolute; transform:translateY(-200%); z-index:10; }
.skip-link:focus { transform:none; }
:focus-visible { outline:2px solid currentColor; outline-offset:2px; }
@media(max-width:48rem) {
  .app-shell { block-size:auto; min-block-size:100dvh; overflow:visible; }
  .app-panes { flex-direction:column; }
  .app-navigation { flex-basis:auto; overflow:visible; }
  .app-workspace, .app-inspector { block-size:auto; }
  .app-inspector-region { inline-size:100% !important; max-inline-size:100%; }
  .app-scroll { overflow:visible; }
  /* At phone widths the document is the sole scroll owner. */
}
